import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { vec2, uv, mix, time, uniform } from 'three/tsl';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();

  // Geometry & material
  const geometry = new PlaneGeometry(1.5, 2);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Text
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    txt.position.set(0, 0.5, 0.01);
    root.add(txt);
  }

  // Cinematic primitives
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // GSAP timelines
  const timelines = [];

  // Hover rise‑in
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(root.position, {
    y: root.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });
  timelines.push(hoverTimeline);

  // Click press‑down (scale)
  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline.to(root.scale, {
    x: 0.97,
    y: 0.97,
    z: 0.97,
    duration: 0.12,
    ease: 'back.out',
  });
  timelines.push(pressTimeline);

  // Handlers
  root.userData.handlers = {
    hoverEnter: () => hoverTimeline.play(),
    hoverLeave: () => hoverTimeline.reverse(),
    click: () => {
      pressTimeline.restart();
      ctx.emit('hub-journal.select', {});
    },
  };

  // Cleanup
  root.userData.cleanup = () => {
    material.dispose();
    geometry.dispose();
    timelines.forEach((t) => t.kill());
    primitiveInstances.forEach((inst) => {
      if (inst && typeof inst.cleanup === 'function') inst.cleanup();
    });
  };

  return root;
}
